from collections import deque

def can_visit_all_rooms(rooms):
    n = len(rooms)
    visited = {0}
    queue = deque([0])
    while queue:
        room = queue.popleft()
        for key in rooms[room]:
            if 0 <= key < n and key not in visited:
                visited.add(key)
                queue.append(key)
    return len(visited) == n
